"""This file contains the Volume View Reconstruction Page Object class for the VolumeView Reconstruction window in XVI."""

import logging
from .. interactions import VolumeViewReconFuncs
from interops.libraries.desktop import AutManager
from interops.libraries.xvi import XviAutController
from interops.libraries.squish_actions.constants import XVI_REGISTRATION_APP_NAME
from typing import Dict

logger = logging.getLogger(__name__)

class VolumeViewReconstruction():

    def __init__(self, host_address="192.168.30.4", aut_attach_retries: int = 2) -> None:
        # Check if squish has already attached to XVI3 AUT, if not attach to it
        # Note: The XVI VolumeView Reconstruction AUT name (xvi3) is the same as the VolumeView Registration AUT
        if not AutManager.is_aut_running(XVI_REGISTRATION_APP_NAME):
            xvi_vol_view_recon_driver = XviAutController.xvi_registration_aut(serverAddress=host_address, serverPort=4322)
            for i in range(aut_attach_retries):
                try:
                    print(f"xvi3 attach attempt no. {i+1}")
                    self.xvi3_volumeview_driver = xvi_vol_view_recon_driver.attach_to_aut(kill_existing_process=True, get_running_aut_pid_retries=200)
                except Exception as e:
                    logger.info(f"Failed to attach to VolumeView Reconstruction window on attempt no: {i+1}. Error: {e}.")
        self.xvi_host_address = host_address

    def ready(self, wait_timeout=3000, retries: int=2) -> bool:
        '''
        Waits for the VolumeView Reconstruction window to be ready.

        Returns:
            bool - True if VolumeView Reconstruction window is ready, False otherwise
        '''
        for i in range(retries):
            try:
                return VolumeViewReconFuncs.wait_for_volume_view_reconstruction_pane(wait_timeout)
            except Exception as e:
                logger.info(f"VolumeView Reconstruction window failed to open or was not recognised on attempt no: {i+1}. Error: {e}.")
        return False

    def select_volume_view_reconstruction_dismiss_button(self) -> None:
        '''
        Clicks the Dismiss button on the VolumeView Reconstruction window
        '''
        VolumeViewReconFuncs.click_volume_view_reconstruction_dismiss_button()

    def select_volume_view_reconstruction_accept_button(self) -> None:
        '''
        Clicks the Accept button on the VolumeView Reconstruction window
        '''
        VolumeViewReconFuncs.click_volume_view_reconstruction_accept_button()

    def edit_comment_and_approve_reconstruction_dialog(self, approval_comment: str) -> None:
        '''
        Checks and waits for the approval dialog to appear, enters the
        specified approval comment or initials and clicks the OK button.
        '''
        VolumeViewReconFuncs.edit_volume_view_reconstruction_approval_comment_field(approval_comment)
        VolumeViewReconFuncs.click_volume_view_reconstruction_approval_ok_button()